const map=document.querySelector('#map'),input=document.querySelector('#search'),suggest=document.querySelector('#suggest'),info=document.querySelector('#info');
const norm=s=>String(s??'').toLocaleLowerCase('pl-PL').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/ł/g,'l').replace(/\s+/g,' ').trim();
const escapeHtml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const searchable=data.map(d=>({...d,query:norm([d.name,d.aliases,d.code].join(' '))}));
const byCode=new Map();data.forEach((d,i)=>{if(!d.regions.length)return;const key=d.code.toUpperCase();if(!byCode.has(key))byCode.set(key,[]);byCode.get(key).push(i)});
const ns='http://www.w3.org/2000/svg',groups=new Map();
for(const [code,indexes] of byCode){const d=data[indexes[0]],g=document.createElementNS(ns,'g');g.classList.add('stall');g.setAttribute('tabindex','0');g.setAttribute('role','button');g.setAttribute('aria-label',`Stoisko ${d.code}, ${d.hall}: ${indexes.map(i=>data[i].name).join(', ')}`);g.setAttribute('aria-pressed','false');
 const title=document.createElementNS(ns,'title');title.textContent=`${d.code} · ${indexes.map(i=>data[i].name).join(', ')}`;g.appendChild(title);
 for(const r of d.regions){const rect=document.createElementNS(ns,'rect');for(const k of ['x','y','w','h'])rect.setAttribute(k==='w'?'width':k==='h'?'height':k,r[k]);rect.setAttribute('rx','1');g.appendChild(rect)}
 g.onclick=()=>select(indexes[0]);g.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select(indexes[0])}};map.appendChild(g);groups.set(code,g)}
let selected=-1,zoom=1,results=[];
function initial(){info.innerHTML=`<div class="eyebrow">PEŁNY KATALOG ORGANIZATORA</div><div class="icon">▧</div><h2>483 wystawców i marek</h2><p>Znajdź wydawnictwo po nazwie, marce lub numerze stoiska. Nazwy możesz wpisywać z polskimi znakami lub bez nich.</p><button class="all-publishers" id="showAll">Przeglądaj całą listę (483) ↗</button><div class="popular"><strong>Na dobry początek</strong><div class="chips"><button data-query="Wydawnictwo ZNAK">Znak ↗</button><button data-query="Czarne">Czarne ↗</button><button data-query="Dwie Siostry">Dwie Siostry ↗</button></div></div>`;
 document.querySelector('#showAll').onclick=()=>{input.value='';renderResults('');input.focus()};info.querySelectorAll('[data-query]').forEach(b=>b.onclick=()=>{const found=findMatches(b.dataset.query);if(found.length)select(found[0])})}
function locationText(d){if(d.code)return `${d.code} · ${d.hall||'Lokalizacja organizatora'}`;return d.hall==='Online'?'Udział online':'Brak lokalizacji w katalogu'}
function findMatches(q){q=norm(q);const words=q.split(' ').filter(Boolean);return searchable.map((d,i)=>({d,i})).filter(({d})=>words.every(w=>d.query.includes(w))).sort((a,b)=>{const rank=d=>!q?0:norm(d.name)===q?0:norm(d.code)===q||d.aliases.split('|').some(a=>norm(a)===q)?1:norm(d.name).startsWith(q)?2:norm(d.name).includes(q)?3:4;return rank(a.d)-rank(b.d)||a.d.name.localeCompare(b.d.name,'pl')||Number(!a.d.regions.length)-Number(!b.d.regions.length)}).map(r=>r.i)}
function renderResults(q){results=findMatches(q);suggest.replaceChildren();input.setAttribute('aria-expanded','true');document.querySelector('#clear').style.display=input.value?'block':'none';
 const status=document.createElement('p');status.className='result-count';status.setAttribute('role','status');status.textContent=results.length?`${results.length} ${results.length===1?'wynik':'wyników'} · pełny katalog: ${data.length} wpisy`:'Nie znaleziono. Spróbuj krótszej nazwy lub numeru stoiska.';suggest.appendChild(status);
 for(const i of results){const d=data[i],b=document.createElement('button');b.type='button';b.innerHTML=`<span>${escapeHtml(d.name)}</span><span class="result-location">${escapeHtml(locationText(d))} ↗</span>`;b.onclick=()=>select(i);b.onkeydown=e=>{if(e.key==='ArrowDown'){e.preventDefault();b.nextElementSibling?.focus()}if(e.key==='ArrowUp'){e.preventDefault();if(b.previousElementSibling?.tagName==='BUTTON')b.previousElementSibling.focus();else input.focus()}if(e.key==='Escape'){closeResults();input.focus()}};suggest.appendChild(b)}}
function closeResults(){suggest.replaceChildren();input.setAttribute('aria-expanded','false')}
function unhighlight(){for(const g of groups.values()){g.classList.remove('selected');g.setAttribute('aria-pressed','false')}}
function select(i){selected=i;const d=data[i];input.value=d.name;closeResults();document.querySelector('#clear').style.display='block';unhighlight();const group=groups.get(d.code.toUpperCase());if(group){group.classList.add('selected');group.setAttribute('aria-pressed','true');map.appendChild(group)}
 const isRoom=d.code&&!/^[ABCDKL]\d/i.test(d.code);const hasLocation=d.regions.length>0;
 info.innerHTML=`<div class="eyebrow">${hasLocation?'ZNALEZIONO NA PLANIE':'WPIS W KATALOGU'}</div><div class="icon">${hasLocation?'✓':'ⓘ'}</div><h2>${escapeHtml(d.name)}</h2>${hasLocation?`<div class="detail">${d.hall==='Lobby'?'Lobby':'Hala '+escapeHtml(d.hall)}<strong class="${isRoom?'room-label':''}">${isRoom?'': 'Stoisko '}${escapeHtml(d.code)}</strong></div><p style="margin-top:16px">Lokalizację zaznaczyliśmy na zielono.</p>`:`<p>${d.hall==='Online'?'Ten wystawca jest oznaczony w katalogu jako uczestnik online.':'Organizator nie podał numeru stoiska ani lokalizacji tego wpisu. Nie możemy wskazać go na planie.'}</p>`}<p style="margin-top:14px;font-size:11px">Dane z oficjalnego katalogu wystawców 2026.</p>`;
 const siblings=hasLocation?(byCode.get(d.code.toUpperCase())||[]).filter(k=>k!==i):[];
 if(siblings.length){const wrap=document.createElement('div');wrap.className='popular';const label=document.createElement('strong');label.textContent=`Na tej samej lokalizacji (${siblings.length})`;wrap.appendChild(label);const list=document.createElement('div');list.className='shared-list';for(const k of siblings){const b=document.createElement('button');b.textContent=data[k].name;b.onclick=()=>select(k);list.appendChild(b)}wrap.appendChild(list);info.appendChild(wrap)}
 info.setAttribute('aria-live','polite');document.querySelector('#mapLabel').textContent=hasLocation?d.hall:'Brak lokalizacji na planie';zoom=hasLocation?3:1;applyZoom()}
function applyZoom(recenter=true){const w=2122/zoom,h=3000/zoom;let cx=1061,cy=1500;if(!recenter){const v=map.getAttribute("viewBox").split(/[ ,]+/).map(Number);cx=v[0]+v[2]/2;cy=v[1]+v[3]/2;}if(recenter&&selected>=0&&data[selected].regions.length){const r=data[selected].regions;const left=Math.min(...r.map(a=>a.x)),right=Math.max(...r.map(a=>a.x+a.w)),top=Math.min(...r.map(a=>a.y)),bottom=Math.max(...r.map(a=>a.y+a.h));cx=(left+right)/2;cy=(top+bottom)/2}map.setAttribute('viewBox',`${Math.max(0,Math.min(2122-w,cx-w/2))} ${Math.max(0,Math.min(3000-h,cy-h/2))} ${w} ${h}`)}
function clear(){input.value='';selected=-1;zoom=1;unhighlight();applyZoom();closeResults();document.querySelector('#clear').style.display='none';document.querySelector('#mapLabel').textContent='Wszystkie hale';initial()}
input.oninput=()=>{if(!input.value.trim()){clear();return}renderResults(input.value)};
input.onkeydown=e=>{if(e.key==='Enter'&&input.value.trim()){const found=findMatches(input.value);if(found.length)select(found[0])}if(e.key==='ArrowDown'){e.preventDefault();if(!suggest.children.length)renderResults(input.value);suggest.querySelector('button')?.focus()}if(e.key==='Escape')closeResults()};
document.querySelector('#plus').onclick=()=>{zoom=Math.min(8,zoom+.5);applyZoom(false)};document.querySelector('#minus').onclick=()=>{zoom=Math.max(1,zoom-.5);applyZoom(false)};document.querySelector('#reset').onclick=()=>{zoom=1;applyZoom()};document.querySelector('#clear').onclick=()=>{clear();input.focus()};document.addEventListener('click',e=>{if(!e.target.closest('.searchbox')&&!e.target.closest('#showAll'))closeResults()});initial();

map.addEventListener("mapnavigate",e=>{zoom=e.detail.zoom});
